import{_ as t,a,b as o,c as r,d as i,e as s,f as n,g as l,h,i as d,j as c,k as m,l as p,m as u,n as _,o as g,p as y,q as b,r as f,s as w,t as k,u as v,v as x,w as q,x as T,y as z,z as S,A}from"./chunks/ScreenSaver2.C6Ib7NV6.js";import{_ as P}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as E}from"./chunks/UImenu.2mWyDoEW.js";import{_ as D}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as B,o as N,c as C,a3 as I}from"./chunks/framework.g9mfNVRQ.js";const F=JSON.parse('{"title":"Main view","description":"","frontmatter":{},"headers":[],"relativePath":"use/mainUI.md","filePath":"use/mainUI.md"}'),U={name:"use/mainUI.md"};function G(O,e,R,L,W,Y){return N(),C("div",null,[...e[0]||(e[0]=[I('<h3 id="meet-the-user-interface" tabindex="-1">Meet the user interface <a class="header-anchor" href="#meet-the-user-interface" aria-label="Permalink to &quot;Meet the user interface&quot;">​</a></h3><p>Welcome to xDrip!</p><img src="'+t+'" style="zoom:50%;"><p>If you&#39;ve just set up xDrip, you want to start with basic customizations:</p><ol><li><a href="./settings.html">Set up the unit you want to display your blood glucose with</a></li><li><a href="./alarms.html">Add alarms</a></li><li>If you&#39;re connecting xDrip to a sensor, <a href="./syncsetup.html">share data to another phone with xDrip</a></li><li>Display xDrip on the phone when <a href="./display.html#numbered-wall-on-locked-screen">screen is locked</a></li><li>Add a <a href="#widget">widget</a> to your phone home screen</li><li>Add a <a href="./../smartwatch/smartwatch.html">smartwatch</a></li><li>Share data with your endocrinologist using <a href="https://www.tidepool.org/" target="_blank" rel="noreferrer">Tidepool</a>, if you have a Tidepool account, just <a href="./cloud.html#tidepool">set up xDrip</a></li><li>Upload your data to <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> (recommended)</li></ol><h3 id="basic-indications" tabindex="-1">Basic indications <a class="header-anchor" href="#basic-indications" aria-label="Permalink to &quot;Basic indications&quot;">​</a></h3><p>You will see these default indications when xDrip receives data.</p><img src="'+a+'" style="zoom:75%;"><ol><li>How long ago was the reading received and what&#39;s the BG difference with the previous value received.</li><li>What&#39;s the last measured BG value.</li><li>What&#39;s the trend with respect to the previous measurement.</li></ol><h5 id="trend-arrow" tabindex="-1">Trend arrow <a class="header-anchor" href="#trend-arrow" aria-label="Permalink to &quot;Trend arrow&quot;">​</a></h5><div class="info custom-block"><p class="custom-block-title">Note</p><p>The arrow gives the trend difference with the previous measurement, other CGM applications use an algorithm to give this indication and the result might not match.<br> In case of missing readings, the arrow might indicate fast rise or drop, always correlate with the indication in <code>1</code>.</p></div><p>You can customize the information shown in <code>1</code> with <a href="./display.html#graph-settings">Graph Settings</a>.</p><p>You can <a href="#blood-drop-menu">customize the trend arrow aspect</a> but not behavior (i.e. it will always use the difference with the previous reading).</p><p>This is how the classic trend arrow will appear, it takes into account the difference between previous and current BG readings.</p><table tabindex="0"><thead><tr><th>BG difference (previous and current)</th><th></th></tr></thead><tbody><tr><td>Changed at most +/- 5mg/dl (0.28 mmol/l)</td><td><img src="'+o+'" style="zoom:75%;"></td></tr><tr><td>Changed more than above and less than +/- 10mg/dl (0.56 mmol/l)</td><td><img src="'+r+'" style="zoom:75%;"></td></tr><tr><td>Changed more than above and less than +/- 17.5mg/dl (0.97 mmol/l)</td><td><img src="'+i+'" style="zoom:75%;"></td></tr><tr><td>Changed more than above</td><td><img src="'+s+'" style="zoom:75%;"></td></tr></tbody></table><h3 id="treatments" tabindex="-1">Treatments <a class="header-anchor" href="#treatments" aria-label="Permalink to &quot;Treatments&quot;">​</a></h3><p>You can log treatments with the syringe icon.</p><img src="'+n+'" style="zoom:75%;"><p>Add one or more elements to your treatment.</p><h4 id="blood-test" tabindex="-1">Blood test <a class="header-anchor" href="#blood-test" aria-label="Permalink to &quot;Blood test&quot;">​</a></h4><p>It will display in the unit selected in xDrip.</p><img src="'+l+'" style="zoom:75%;"><h4 id="grams-of-carbs" tabindex="-1">Grams of carbs <a class="header-anchor" href="#grams-of-carbs" aria-label="Permalink to &quot;Grams of carbs&quot;">​</a></h4><img src="'+h+'" style="zoom:75%;"><h4 id="units-of-insulin" tabindex="-1">Units of insulin <a class="header-anchor" href="#units-of-insulin" aria-label="Permalink to &quot;Units of insulin&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you enabled <a href="./predictions.html#multiple-insulin-types">multiple insulin types</a>, you should also select the insulin type for this treatment.</p></div><img src="'+d+'" style="zoom:75%;"><h4 id="time" tabindex="-1">Time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Time&quot;">​</a></h4><p>And optionally the time of the treatment (if not now) expressed in 24-hour format, with or without a separator.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>You can select a treatment time from 23 hours in the past, up to 1 hour in the future.</p></div><img src="'+c+'" style="zoom:75%;"><p>Treatments are valid when the green check mark appears in the upper right corner. Touch it to confirm the entries.</p><img src="'+m+'" style="zoom:75%;"><p>A summary is displayed. Touch the green <code>+</code> icon to confirm or red <code>x</code> icon to discard.</p><img src="'+p+'" style="zoom:75%;"><p>Once done, new symbols will appear on your graph.</p><p>Units and carbs show like this:</p><img src="'+u+'" style="zoom:75%;"><p>And blood tests like this (note the symbol is square unlike <a href="./../calibrate/calibrate.html">calibrations</a> that are round):</p><img src="'+_+'" style="zoom:75%;"><h4 id="edit-and-delete" tabindex="-1">Edit and delete <a class="header-anchor" href="#edit-and-delete" aria-label="Permalink to &quot;Edit and delete&quot;">​</a></h4><p>When visible, you can delete treatments like this:</p><ul><li>Touch the treatment, look at the bottom of the screen: touch Add Note</li></ul><div style="background-color:black;color:white;text-align:left;">  18:45 Treatment <span style="color:cyan;float:right;">ADD NOTE </span></div><p>or Blood Test.</p><div style="background-color:black;color:white;text-align:left;">  10:06 85 mg/dl <span style="color:cyan;float:right;">BLOOD TEST </span></div><ul><li>You can enter a note or touch DELETE to delete the entry. This applies to blood tests, carbs and insulin.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Treatment Note</p><p><span style="color:cyan;">_____________________________________________________________________________________</span><br><small>Default to voice input next time</small> ☐</p><p><span style="color:cyan;float:left;">DELETE </span><span style="color:cyan;float:right;">CANCEL DONE </span></p></div><p>Note that if you touch a blood test and edit it you can also convert it to a calibration using CALIBRATE. This is possible if you didn&#39;t select <strong>Never use them</strong> in <a href="./../calibrate/advancedcal.html">Advanced Calibrations</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Blood Test Action</p><p>What would you like to do?</p><p><span style="color:cyan;float:left;">NOTHING </span><span style="color:cyan;float:right;">DELETE CALIBRATE </span></p></div><h5 id="spoken-treatments" tabindex="-1">Spoken treatments <a class="header-anchor" href="#spoken-treatments" aria-label="Permalink to &quot;Spoken treatments&quot;">​</a></h5><p>You can use the microphone icon to verbally enter treatments or advanced commands.</p><p>A long touch on the microphone icon will allow you to write <a href="./spokencommands.html">advanced commands</a>.</p><h3 id="treatment-notes" tabindex="-1">Treatment notes <a class="header-anchor" href="#treatment-notes" aria-label="Permalink to &quot;Treatment notes&quot;">​</a></h3><p>Independently of treatments you can enter notes.</p><img src="'+g+'" style="zoom:75%;"><p>Enter the comment you want (like slow acting insulin units), or use the microphone icon to speak the note.</p><div class="admonition xdripitem"><p class="admonition-title">Treatment Note</p><p><span style="color:cyan;">_____________________________________________________________________________________</span><br><small>Default to voice input next time</small> ☐</p><p><span style="color:cyan;float:left;">DELETE </span><span style="color:cyan;float:right;">CANCEL DONE </span></p></div><p>They will be added to the graph like this:</p><img src="'+y+'" style="zoom:75%;"><p>By touching them you can edit or delete them.</p><h3 id="undo-and-redo" tabindex="-1">Undo and Redo <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Undo and Redo&quot;">​</a></h3><ol><li>Undo will step backwards through treatments simulations, calibrations and notes. After 30 minutes it will hide again.</li><li>Redo can step forwards through treatments simulations, calibrations and notes. After 30 minutes it will hide again.</li></ol><img src="'+b+'" style="zoom:77%;"><h3 id="main-menu" tabindex="-1"><a href="./hamburger.html">Main menu</a> <a class="header-anchor" href="#main-menu" aria-label="Permalink to &quot;[Main menu](./hamburger)&quot;">​</a></h3><p>Also called hamburger or drawer menu, this is the main menu in which you&#39;ll be able to find or add the most common actions you need and also all settings and customizations.</p><img src="'+P+'" style="zoom:75%;"><h3 id="blood-drop-menu" tabindex="-1">Blood drop menu <a class="header-anchor" href="#blood-drop-menu" aria-label="Permalink to &quot;Blood drop menu&quot;">​</a></h3><p>With a long touch on the central area between the main and three dots menus you can open another menu for customizing the user interface.</p><img src="'+E+'" style="zoom:75%;"><h5 id="source-wizard-button" tabindex="-1">Source Wizard Button <a class="header-anchor" href="#source-wizard-button" aria-label="Permalink to &quot;Source Wizard Button&quot;">​</a></h5><p>Shows the button driving you through the data source selection as described <a href="./../install/datasource.html">here</a>.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">   START SOURCE SETUP WIZARD </span></p></div><h5 id="show-time-buttons" tabindex="-1">Show Time Buttons <a class="header-anchor" href="#show-time-buttons" aria-label="Permalink to &quot;Show Time Buttons&quot;">​</a></h5><p>Adds a row of four presets for the main graph time range: 24, 12, 6 and 3 hours.<br> If you long press a time button you can lock the view to that time period.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">  24 HOUR </span>  <span style="background-color:grey;color:white;">  12 HOUR </span>  <span style="background-color:grey;color:white;">  6 HOUR </span>  <span style="background-color:grey;color:white;">  3 HOUR </span></p></div><h5 id="locked-time-period-always-used" tabindex="-1">Locked time period always used <a class="header-anchor" href="#locked-time-period-always-used" aria-label="Permalink to &quot;Locked time period always used&quot;">​</a></h5><p>Sets the last modified display time period as default.</p><h5 id="show-chart-preview" tabindex="-1">Show Chart Preview <a class="header-anchor" href="#show-chart-preview" aria-label="Permalink to &quot;Show Chart Preview&quot;">​</a></h5><p>Enables or disables the 24 hours small chart in the lower screen area.</p><img src="'+f+'" style="zoom:75%;"><h5 id="show-collector-status" tabindex="-1">Show Collector Status <a class="header-anchor" href="#show-collector-status" aria-label="Permalink to &quot;Show Collector Status&quot;">​</a></h5><p>Shows information messages regarding the collector status below the main graph.</p><img src="'+w+'" style="zoom:75%;"><h5 id="show-sensor-expiry" tabindex="-1">Show Sensor Expiry <a class="header-anchor" href="#show-sensor-expiry" aria-label="Permalink to &quot;Show Sensor Expiry&quot;">​</a></h5><p>Displays the remaining time before sensor expiry below the main graph.</p><img src="'+k+'" style="zoom:75%;"><h5 id="show-graphical-trend-arrow" tabindex="-1">Show Graphical Trend Arrow <a class="header-anchor" href="#show-graphical-trend-arrow" aria-label="Permalink to &quot;Show Graphical Trend Arrow&quot;">​</a></h5><p>Adds an option allowing you to select other arrow styles.</p><p>Use the wrench <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_wrench_grey600_48dp.png" style="width:3%;"> and drop down menu ▼ to select them.<br> Color arrows include a hue cursor to change color.</p><p>Graphical trend arrows&#39; angle depends on the reading difference with the previous value (5 minutes) and not only flat/45/90 degree like the classic arrows.</p><img src="'+v+'" style="zoom:90%;"><h3 id="three-dots-menu" tabindex="-1"><a href="./3dotsmenu.html">Three dots menu</a> <a class="header-anchor" href="#three-dots-menu" aria-label="Permalink to &quot;[Three dots menu](./3dotsmenu)&quot;">​</a></h3><p>This menu contains some shortcuts to settings and other unique functions.</p><img src="'+D+'" style="zoom:75%;"><h3 id="widget" tabindex="-1">Widget <a class="header-anchor" href="#widget" aria-label="Permalink to &quot;Widget&quot;">​</a></h3><p>If your phone supports widgets, long touch an empty area on your home screen and select widgets.<br> Browse the apps until you find xDrip.</p><img src="'+x+'" style="zoom:75%;"><p>Keep your finger on the widget and drag it to the position you want it to be displayed.</p><img src="'+q+'" style="zoom:75%;"><p>You can resize it using the blue dots.</p><img src="'+T+'" style="zoom:75%;"><p>And make it the size you like. Then you can customize colors and contents aspect in <a href="./display.html">display settings</a>.</p><img src="'+z+'" style="zoom:75%;"><h3 id="screensaver" tabindex="-1">Screensaver <a class="header-anchor" href="#screensaver" aria-label="Permalink to &quot;Screensaver&quot;">​</a></h3><p>If your phone supports this feature you can enable xDrip as a screensaver in Android Settings.</p><img src="'+S+'" style="zoom:75%;"><p>When you put your phone on charge it will display a small graph and the BG value.</p><img src="'+A+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 15/12/2024</em></a></p>',111)])])}const J=B(U,[["render",G]]);export{F as __pageData,J as default};
